            top: 0;
            left: 0;
            width: 100%;
            height: 5px;
            background: var(--accent);
        }

        /* ===========================================
           CONTENT SLIDES
           =========================================== */
        .columns-2 {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1.5rem, 3vw, 3rem);
            align-items: start;
        }

        .columns-3 {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: clamp(1rem, 2vw, 2rem);
            align-items: start;
        }

        @media (max-width: 768px) {
            .columns-2, .columns-3 {
                grid-template-columns: 1fr;
            }
        }

        .challenge-card {
            background: var(--bg-primary);
            border: 1px solid var(--border);
            border-top: 3px solid var(--accent);
            padding: clamp(1rem, 2vw, 1.5rem);
            border-radius: 2px;
        }

        .challenge-card h3 {
            font-size: var(--h3-size);
            margin-bottom: clamp(0.3rem, 0.8vh, 0.6rem);
        }

        .challenge-card p {
            font-size: var(--small-size);
        }

        .challenge-card .number {
            font-family: var(--font-display);
            font-weight: 900;
            font-size: clamp(1.5rem, 3vw, 2.5rem);
            color: var(--accent);
            opacity: 0.3;
            margin-bottom: clamp(0.3rem, 0.5vh, 0.5rem);
        }

        /* Framework diagram */
        .framework-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.6rem, 1.2vw, 1rem);
        }

        .framework-item {
            background: var(--bg-primary);
            border: 1px solid var(--border);
            border-left: 3px solid var(--accent-secondary);
            padding: clamp(0.6rem, 1.2vw, 1rem);
            font-size: var(--small-size);
        }

        .framework-item.novel {
            border-left-color: var(--accent);
            background: rgba(230, 51, 18, 0.03);
        }

        .framework-item .technique {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--body-size);
            color: var(--text-primary);
            margin-bottom: clamp(0.15rem, 0.3vh, 0.3rem);
        }

        .framework-item .addresses {
            font-size: var(--label-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.06em;
            font-weight: 600;
        }

        /* Bar chart */
        .bar-chart {
            display: flex;
            align-items: flex-end;
            justify-content: center;
            gap: clamp(1rem, 3vw, 3rem);
            height: clamp(180px, 40vh, 320px);
            padding-top: clamp(1rem, 2vh, 2rem);
        }

        .bar-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: clamp(0.3rem, 0.6vh, 0.5rem);
        }

        .bar {
            width: clamp(50px, 8vw, 90px);
            border-radius: 2px 2px 0 0;
            position: relative;
            transition: height 1s var(--ease-out-expo);
        }

        .bar-value {
            font-family: var(--font-display);
            font-weight: 900;
            font-size: clamp(1rem, 2vw, 1.8rem);
            color: var(--text-primary);
        }

        .bar-label {
            font-size: var(--label-size);
            color: var(--text-muted);
            text-align: center;
            max-width: clamp(60px, 10vw, 100px);
            font-weight: 600;
        }

        .bar.vanilla { background: #d1d5db; }
        .bar.deepseek { background: #93c5fd; }
        .bar.dapo { background: #6366f1; }
        .bar.vapo { background: var(--accent); }

        /* Lambda diagram */
        .lambda-diagram {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1.5rem, 3vw, 3rem);
            margin-top: var(--content-gap);
        }

        .lambda-box {
            background: var(--bg-primary);
            border: 1px solid var(--border);
            padding: clamp(1rem, 2vw, 1.5rem);
            text-align: center;
            position: relative;
        }

        .lambda-box h3 {
            font-size: var(--body-size);
            margin-bottom: clamp(0.3rem, 0.5vh, 0.5rem);
        }

        .lambda-box .lambda-val {
            font-family: var(--font-display);
            font-weight: 900;
            font-size: clamp(1.5rem, 4vw, 3rem);
            color: var(--accent-secondary);
        }

        .lambda-box .lambda-desc {
            font-size: var(--small-size);
            color: var(--text-muted);
            margin-top: clamp(0.2rem, 0.4vh, 0.4rem);
        }

        .lambda-box .tradeoff {
            margin-top: clamp(0.4rem, 0.8vh, 0.8rem);
            font-size: var(--label-size);
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.06em;
        }

        .lambda-box .tradeoff.low-var { color: var(--accent-success); }
        .lambda-box .tradeoff.low-bias { color: var(--accent-secondary); }

        /* Training curve */
        .curve-container {
            background: var(--bg-primary);
            border: 1px solid var(--border);
            padding: clamp(1rem, 2vw, 1.5rem);
            position: relative;
            height: clamp(140px, 28vh, 220px);
        }

        .curve-labels {
            display: flex;
            justify-content: space-between;
            margin-top: clamp(0.5rem, 1vh, 1rem);
            font-size: var(--label-size);
            color: var(--text-muted);
        }

        .curve-legend {
            display: flex;
            gap: clamp(1rem, 2vw, 2rem);
            font-size: var(--small-size);
            margin-top: clamp(0.4rem, 0.8vh, 0.8rem);
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 0.5vw, 0.5rem);
        }

        .legend-dot {
            width: clamp(8px, 1vw, 12px);
            height: 3px;
            border-radius: 1px;
        }

        /* Ablation waterfall */
        .ablation-table {
            width: 100%;
            border-collapse: collapse;
        }

        .ablation-table th,
        .ablation-table td {
            padding: clamp(0.3rem, 0.6vh, 0.6rem) clamp(0.5rem, 1vw, 1rem);
            text-align: left;
            font-size: var(--small-size);
            border-bottom: 1px solid var(--border);
        }

        .ablation-table th {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--label-size);
            text-transform: uppercase;
            letter-spacing: 0.06em;
            color: var(--text-muted);
        }

        .ablation-table .score {
            font-family: var(--font-display);
            font-weight: 800;
            font-size: var(--body-size);
        }

        .ablation-table .drop {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--small-size);
            color: var(--accent);
        }

        .ablation-table .critical {
            background: rgba(230, 51, 18, 0.05);
        }

        .drop-bar {
            height: clamp(6px, 0.8vh, 10px);
            background: var(--accent);
            border-radius: 1px;
            opacity: 0.7;
            margin-top: 2px;
        }

        /* Takeaways */
        .takeaway-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: clamp(0.6rem, 1.2vh, 1.2rem);
        }

        .takeaway-list li {
            padding-left: clamp(1rem, 2vw, 1.5rem);
            border-left: 3px solid var(--accent);
            font-size: var(--body-size);
        }

        .takeaway-list li strong {
            display: block;
            font-family: var(--font-display);
            font-weight: 700;
            color: var(--text-primary);
            margin-bottom: 2px;
        }

        /* Key stat callout */
        .stat-callout {
            display: inline-flex;
            align-items: baseline;
            gap: clamp(0.3rem, 0.5vw, 0.5rem);
            margin-top: var(--element-gap);
        }

        .stat-callout .number {
            font-family: var(--font-display);
            font-weight: 900;
            font-size: clamp(2rem, 5vw, 4rem);
            color: var(--accent);
            line-height: 1;
        }

        .stat-callout .unit {
            font-size: var(--subtitle-size);
            color: var(--text-muted);
        }

        /* Progress bar */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: var(--accent);
            z-index: 1000;
            transition: width 0.3s ease;
        }

        /* Nav dots */
        .nav-dots {
            position: fixed;
            right: clamp(1rem, 2vw, 2rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(6px, 1vh, 10px);
            z-index: 100;
        }

        .nav-dot {
            width: clamp(6px, 0.6vw, 8px);
            height: clamp(6px, 0.6vw, 8px);
            border-radius: 50%;
            background: var(--border);
            cursor: pointer;
            transition: background 0.3s, transform 0.3s;
        }

        .nav-dot.active {
            background: var(--accent);
            transform: scale(1.4);
        }

        /* SVG chart styles */
        .chart-svg {
            width: 100%;
            height: clamp(120px, 25vh, 200px);
        }

        .comparison-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1vw, 1rem);
            margin-top: var(--content-gap);
        }

        .comparison-row .key-point {
            background: var(--bg-primary);
            border: 1px solid var(--border);
            padding: clamp(0.6rem, 1vw, 1rem);
            flex: 1;
            font-size: var(--small-size);
        }

        .comparison-row .key-point strong {
            font-family: var(--font-display);
            font-weight: 700;
            display: block;
            margin-bottom: 2px;
        }
    </style>
</head>
<body>
    <div class="progress-bar" id="progressBar"></div>
